{"path": "/tmp/sv-e8ad36719a5a4dc29a4d0c9d4073290a/Components/Chat/MessageArea.razor", "file_text": "@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-area">
    <div class="area-header">
        <h2># @ChannelName</h2>
        @if (!string.IsNullOrWhiteSpace(ChannelDescription))
        {
            <span class="area-desc">@ChannelDescription</span>
        }
    </div>

    <div class="message-list" @ref="_messageListRef">
        @if (HasMore)
        {
            <div @ref="_sentinelRef" class="load-more-sentinel">
                @if (IsLoadingMore)
                {
                    <span class="loading-indicator">Loading…</span>
                }
            </div>
        }
        @foreach (var msg in Messages)
        {
            <ChatMessage Message="msg"
                         ReplyCount="GetReplyCount(msg.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
        <div @ref="_bottomRef"></div>
    </div>

    <div class="compose-area">
        <textarea class="compose-input"
                  @bind="NewMessage"
                  @bind:event="oninput"
                  @onkeydown="HandleKeyDown"
                  placeholder="Message #@ChannelName"
                  rows="1"></textarea>
        <button class="send-btn" disabled="@string.IsNullOrWhiteSpace(NewMessage)" @onclick="HandleSend">
            Send
        </button>
    </div>
</div>

@code {
    private string NewMessage = "";
    private ElementReference _messageListRef;
    private ElementReference _sentinelRef;
    private ElementReference _bottomRef;
    private IJSObjectReference? _jsModule;
    private DotNetObjectReference<MessageArea>? _dotNetRef;
    private bool _shouldScrollToBottom = true;
    private int _previousMessageCount;

    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string? ChannelDescription { get; set; }
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ReplyCounts { get; set; } = [];
    [Parameter] public bool HasMore { get; set; }
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private int GetReplyCount(int messageId) =>
        ReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _jsModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-e8ad36719a5a4dc29a4d0c9d4073290a/Components/Chat/MessageArea.razor.js");
        }

        if (_shouldScrollToBottom && _jsModule is not null)
        {
            await _jsModule.InvokeVoidAsync("scrollToBottom", _bottomRef);
            _shouldScrollToBottom = false;
        }

        if (HasMore && _jsModule is not null && _dotNetRef is not null)
        {
            await _jsModule.InvokeVoidAsync("observeSentinel", _sentinelRef, _dotNetRef);
        }
    }

    protected override void OnParametersSet()
    {
        if (Messages.Count != _previousMessageCount && Messages.Count > 0)
        {
            // Scroll to bottom only on channel switch (count reset) or new message sent
            if (Messages.Count < _previousMessageCount || Messages.Count == _previousMessageCount + 1)
            {
                _shouldScrollToBottom = true;
            }
            _previousMessageCount = Messages.Count;
        }
    }

    [JSInvokable]
    public async Task OnSentinelVisible()
    {
        if (!IsLoadingMore && HasMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await HandleSend();
        }
    }

    private async Task HandleSend()
    {
        var content = NewMessage?.Trim();
        if (string.IsNullOrEmpty(content)) return;
        NewMessage = "";
        _shouldScrollToBottom = true;
        await OnSendMessage.InvokeAsync(content);
    }

    public async ValueTask DisposeAsync()
    {
        if (_jsModule is not null)
        {
            try { await _jsModule.InvokeVoidAsync("cleanup"); } catch { }
            try { await _jsModule.DisposeAsync(); } catch { }
        }
        _dotNetRef?.Dispose();
    }
}
"}

