{"path": "/tmp/sv-e8ad36719a5a4dc29a4d0c9d4073290a/Components/Chat/MessageArea.razor.js", "file_text": "let observer = null;

export function observeSentinel(sentinel, dotNetRef) {
    if (observer) observer.disconnect();
    if (!sentinel) return;

    observer = new IntersectionObserver(entries => {
        if (entries[0]?.isIntersecting) {
            dotNetRef.invokeMethodAsync('OnSentinelVisible');
        }
    }, { threshold: 0.1 });

    observer.observe(sentinel);
}

export function scrollToBottom(element) {
    if (element) {
        element.scrollIntoView({ behavior: 'instant' });
    }
}

export function cleanup() {
    if (observer) {
        observer.disconnect();
        observer = null;
    }
}
"}

{"path": "/tmp/sv-e8ad36719a5a4dc29a4d0c9d4073290a/Components/Chat/ThreadPanel.razor", "file_text": "<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <ChatMessage Message="RootMessage" IsThreadView="true" />
        </div>

        <div class="thread-divider">
            <span>@Replies.Count @(Replies.Count == 1 ? "reply" : "replies")</span>
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <ChatMessage Message="reply" IsThreadView="true" />
            }
        </div>

        <div class="thread-compose">
            <textarea class="thread-input"
                      @bind="ReplyText"
                      @bind:event="oninput"
                      @onkeydown="HandleKeyDown"
                      placeholder="Reply…"
                      rows="1"></textarea>
            <button class="reply-btn" disabled="@string.IsNullOrWhiteSpace(ReplyText)" @onclick="HandleReply">
                Reply
            </button>
        </div>
    }
</div>

@code {
    private string ReplyText = "";

    [Parameter, EditorRequired] public Message? RootMessage { get; set; }
    [Parameter, EditorRequired] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await HandleReply();
        }
    }

    private async Task HandleReply()
    {
        var content = ReplyText?.Trim();
        if (string.IsNullOrEmpty(content)) return;
        ReplyText = "";
        await OnSendReply.InvokeAsync(content);
    }
}
"}

