toolArgs.file_text:
.chat-message {
    padding: 8px 16px;
    position: relative;
    border-radius: 4px;
    transition: background 0.1s;
}

.chat-message:hover {
    background: var(--msg-hover-bg, #f8f8f8);
}

.chat-message.thread-reply {
    padding: 6px 12px;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.938rem;
    color: var(--text-primary, #1d1c1d);
}

.timestamp {
    font-size: 0.75rem;
    color: var(--text-muted, #616061);
}

.message-content {
    font-size: 0.938rem;
    line-height: 1.5;
    color: var(--text-primary, #1d1c1d);
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    background: var(--reaction-bg, #f0f0f0);
    border: 1px solid var(--border-color, #ddd);
    border-radius: 12px;
    padding: 1px 8px;
    font-size: 0.813rem;
    cursor: default;
}

.thread-link {
    display: inline-block;
    background: none;
    border: none;
    color: var(--accent, #1264a3);
    font-size: 0.813rem;
    font-weight: 600;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 2px;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -12px;
    right: 12px;
    display: flex;
    gap: 2px;
    background: var(--surface-raised, #fff);
    border: 1px solid var(--border-color, #ddd);
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1);
}

.action-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    padding: 4px 6px;
    border-radius: 4px;
    line-height: 1;
    transition: background 0.15s;
}

.action-btn:hover {
    background: var(--hover-bg, #f0f0f0);
}

.react-wrapper {
    position: relative;
}

