.channel-sidebar {
    display: flex;
    flex-direction: column;
    background: var(--sidebar-bg, #3f0e40);
    color: var(--sidebar-text, #cfc3cf);
    height: 100%;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 12px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.sidebar-header h2 {
    margin: 0;
    font-size: 1.125rem;
    font-weight: 700;
    color: #fff;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.channel-item {
    display: block;
    width: 100%;
    text-align: left;
    background: none;
    border: none;
    color: var(--sidebar-text, #cfc3cf);
    padding: 6px 16px;
    cursor: pointer;
    transition: background 0.1s;
    font-family: inherit;
    font-size: inherit;
}

.channel-item:hover {
    background: rgba(255, 255, 255, 0.08);
}

.channel-item.active {
    background: var(--sidebar-active-bg, #1164a3);
    color: #fff;
}

.channel-name-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.channel-name {
    font-size: 0.938rem;
    font-weight: 500;
}

.channel-item.active .channel-name,
.channel-item:has(.unread-badge) .channel-name {
    font-weight: 700;
    color: #fff;
}

.unread-badge {
    background: var(--badge-bg, #cd2553);
    color: #fff;
    font-size: 0.75rem;
    font-weight: 700;
    border-radius: 10px;
    padding: 1px 7px;
    min-width: 18px;
    text-align: center;
    line-height: 1.4;
}

.channel-desc {
    display: block;
    font-size: 0.75rem;
    opacity: 0.7;
    margin-top: 1px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

