toolArgs.file_text:
.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: var(--surface, #fff);
}

.area-header {
    padding: 12px 20px;
    border-bottom: 1px solid var(--border-color, #ddd);
    flex-shrink: 0;
}

.area-header h2 {
    margin: 0;
    font-size: 1.125rem;
    font-weight: 700;
    color: var(--text-primary, #1d1c1d);
}

.area-desc {
    font-size: 0.813rem;
    color: var(--text-muted, #616061);
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.load-more-sentinel {
    text-align: center;
    padding: 8px;
    min-height: 1px;
}

.loading-indicator {
    font-size: 0.813rem;
    color: var(--text-muted, #616061);
}

.compose-area {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid var(--border-color, #ddd);
    flex-shrink: 0;
}

.compose-input {
    flex: 1;
    border: 1px solid var(--border-color, #ccc);
    border-radius: 8px;
    padding: 8px 12px;
    font-size: 0.938rem;
    font-family: inherit;
    resize: none;
    outline: none;
    min-height: 38px;
    max-height: 120px;
}

.compose-input:focus {
    border-color: var(--accent, #1264a3);
    box-shadow: 0 0 0 1px var(--accent, #1264a3);
}

.send-btn {
    background: var(--accent, #007a5a);
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 8px 16px;
    font-size: 0.875rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    transition: opacity 0.15s;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: default;
}

.send-btn:not(:disabled):hover {
    opacity: 0.9;
}

