.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: var(--surface, #fff);
    border-left: 1px solid var(--border-color, #ddd);
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid var(--border-color, #ddd);
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: var(--text-muted, #616061);
    padding: 4px 8px;
    border-radius: 4px;
    line-height: 1;
    transition: background 0.15s;
}

.close-btn:hover {
    background: var(--hover-bg, #f0f0f0);
    color: var(--text-primary, #1d1c1d);
}

.thread-root {
    padding: 8px 0;
    border-bottom: 1px solid var(--border-color, #eee);
}

.thread-divider {
    padding: 8px 16px;
    font-size: 0.75rem;
    color: var(--text-muted, #616061);
    font-weight: 600;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 4px 0;
}

.thread-compose {
    display: flex;
    align-items: flex-end;
    gap: 8px;
    padding: 12px 12px;
    border-top: 1px solid var(--border-color, #ddd);
    flex-shrink: 0;
}

.thread-input {
    flex: 1;
    border: 1px solid var(--border-color, #ccc);
    border-radius: 8px;
    padding: 8px 12px;
    font-size: 0.875rem;
    font-family: inherit;
    resize: none;
    outline: none;
    min-height: 36px;
    max-height: 100px;
}

.thread-input:focus {
    border-color: var(--accent, #1264a3);
    box-shadow: 0 0 0 1px var(--accent, #1264a3);
}

.reply-btn {
    background: var(--accent, #007a5a);
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 8px 14px;
    font-size: 0.813rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    transition: opacity 0.15s;
}

.reply-btn:disabled {
    opacity: 0.5;
    cursor: default;
}

.reply-btn:not(:disabled):hover {
    opacity: 0.9;
}

