arguments.file_text:
@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-col">
        <ChannelSidebar Channels="_channels"
                        SelectedChannelId="_selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-col @(_threadOpen ? "with-thread" : "")">
        @if (_selectedChannel is not null)
        {
            <MessageArea ChannelName="@_selectedChannel.Name"
                         ChannelDescription="@_selectedChannel.Description"
                         Messages="_messages"
                         ReplyCounts="_replyCounts"
                         HasMore="_hasMore"
                         IsLoadingMore="_isLoadingMore"
                         OnLoadMore="LoadOlderMessages"
                         OnSendMessage="SendMessage"
                         OnOpenThread="OpenThread"
                         OnReact="AddReaction" />
        }
    </div>

    @if (_threadOpen)
    {
        <div class="thread-col">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private int _selectedChannelId;
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _replyCounts = [];
    private int _skip;
    private bool _hasMore = true;
    private bool _isLoadingMore;

    private bool _threadOpen;
    private int _threadRootId;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _skip = 0;
        _hasMore = true;
        _messages = [];
        _replyCounts = [];
        CloseThread();

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = loaded;
        _skip = loaded.Count;
        _hasMore = loaded.Count >= PageSize;

        ComputeReplyCounts();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count in local list
        _channels = _channels.Select(c =>
            c.Id == channelId ? c with { UnreadCount = 0 } : c
        ).ToList();
    }

    private async Task LoadOlderMessages()
    {
        if (_isLoadingMore || !_hasMore) return;
        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_selectedChannelId, _skip, PageSize);
        if (older.Count > 0)
        {
            _messages = [.. older, .. _messages];
            _skip += older.Count;
            ComputeReplyCounts();
        }
        _hasMore = older.Count >= PageSize;
        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages = [.. _messages, msg];
        _skip++;
        ComputeReplyCounts();
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootId = rootMessageId;
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);

        var threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadRootMessage ??= threadMessages.FirstOrDefault(m => m.Id == rootMessageId);
        _threadReplies = threadMessages.Where(m => m.Id != rootMessageId).ToList();
        _threadOpen = true;

        ComputeReplyCounts();
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _threadRootId);
        _threadReplies = [.. _threadReplies, reply];
        _messages = [.. _messages, reply];
        _skip++;
        ComputeReplyCounts();
    }

    private async Task AddReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh the message list to reflect the new reaction
        var refreshed = await ChatService.GetMessagesAsync(_selectedChannelId, 0, _skip);
        _messages = refreshed;
        ComputeReplyCounts();
    }

    private void ComputeReplyCounts()
    {
        _replyCounts = _messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());

        // Also include thread replies that may not be in the main list
        if (_threadOpen && _threadReplies.Count > 0)
        {
            _replyCounts[_threadRootId] = Math.Max(
                _replyCounts.GetValueOrDefault(_threadRootId),
                _threadReplies.Count);
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.sidebar-col {
    flex: 0 0 20%;
    min-width: 200px;
    max-width: 280px;
}

.main-col {
    flex: 1;
    min-width: 0;
    border-right: none;
}

.main-col.with-thread {
    flex: 0 0 55%;
}

.thread-col {
    flex: 0 0 25%;
    min-width: 260px;
    max-width: 400px;
}

@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-col">
        <ChannelSidebar Channels="_channels"
                        SelectedChannelId="_selectedChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-col @(_threadOpen ? "with-thread" : "")">
        @if (_selectedChannel is not null)
        {
            <MessageArea ChannelName="@_selectedChannel.Name"
                         ChannelDescription="@_selectedChannel.Description"
                         Messages="_messages"
                         ReplyCounts="_replyCounts"
                         HasMore="_hasMore"
                         IsLoadingMore="_isLoadingMore"
                         OnLoadMore="LoadOlderMessages"
                         OnSendMessage="SendMessage"
                         OnOpenThread="OpenThread"
                         OnReact="AddReaction" />
        }
    </div>

    @if (_threadOpen)
    {
        <div class="thread-col">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private int _selectedChannelId;
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _replyCounts = [];
    private int _skip;
    private bool _hasMore = true;
    private bool _isLoadingMore;

    private bool _threadOpen;
    private int _threadRootId;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _selectedChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _skip = 0;
        _hasMore = true;
        _messages = [];
        _replyCounts = [];
        CloseThread();

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messages = loaded;
        _skip = loaded.Count;
        _hasMore = loaded.Count >= PageSize;

        ComputeReplyCounts();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count in local list
        _channels = _channels.Select(c =>
            c.Id == channelId ? c with { UnreadCount = 0 } : c
        ).ToList();
    }

    private async Task LoadOlderMessages()
    {
        if (_isLoadingMore || !_hasMore) return;
        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_selectedChannelId, _skip, PageSize);
        if (older.Count > 0)
        {
            _messages = [.. older, .. _messages];
            _skip += older.Count;
            ComputeReplyCounts();
        }
        _hasMore = older.Count >= PageSize;
        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages = [.. _messages, msg];
        _skip++;
        ComputeReplyCounts();
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootId = rootMessageId;
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);

        var threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadRootMessage ??= threadMessages.FirstOrDefault(m => m.Id == rootMessageId);
        _threadReplies = threadMessages.Where(m => m.Id != rootMessageId).ToList();
        _threadOpen = true;

        ComputeReplyCounts();
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _threadRootId);
        _threadReplies = [.. _threadReplies, reply];
        _messages = [.. _messages, reply];
        _skip++;
        ComputeReplyCounts();
    }

    private async Task AddReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh the message list to reflect the new reaction
        var refreshed = await ChatService.GetMessagesAsync(_selectedChannelId, 0, _skip);
        _messages = refreshed;
        ComputeReplyCounts();
    }

    private void ComputeReplyCounts()
    {
        _replyCounts = _messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .ToDictionary(g => g.Key, g => g.Count());

        // Also include thread replies that may not be in the main list
        if (_threadOpen && _threadReplies.Count > 0)
        {
            _replyCounts[_threadRootId] = Math.Max(
                _replyCounts.GetValueOrDefault(_threadRootId),
                _threadReplies.Count);
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.sidebar-col {
    flex: 0 0 20%;
    min-width: 200px;
    max-width: 280px;
}

.main-col {
    flex: 1;
    min-width: 0;
    border-right: none;
}

.main-col.with-thread {
    flex: 0 0 55%;
}

.thread-col {
    flex: 0 0 25%;
    min-width: 260px;
    max-width: 400px;
}

