+            c.Id == channelId ? c with { UnreadCount = 0 } : c
+        ).ToList();
+    }
+
+    private async Task LoadOlderMessages()
+    {
+        if (_isLoadingMore || !_hasMore) return;
+        _isLoadingMore = true;
+        StateHasChanged();
+
+        var older = await ChatService.GetMessagesAsync(_selectedChannelId, _skip, PageSize);
+        if (older.Count > 0)
+        {
+            _messages = [.. older, .. _messages];
+            _skip += older.Count;
+            ComputeReplyCounts();
+        }
+        _hasMore = older.Count >= PageSize;
+        _isLoadingMore = false;
+    }
+
+    private async Task SendMessage(string content)
+    {
+        var msg = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
+        _messages = [.. _messages, msg];
+        _skip++;
+        ComputeReplyCounts();
+    }
+
+    private async Task OpenThread(int rootMessageId)
+    {
+        _threadRootId = rootMessageId;
+        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
+
+        var threadMessages = await ChatService.GetThreadAsync(rootMessageId);
+        _threadRootMessage ??= threadMessages.FirstOrDefault(m => m.Id == rootMessageId);
+        _threadReplies = threadMessages.Where(m => m.Id != rootMessageId).ToList();
+        _threadOpen = true;
+
+        ComputeReplyCounts();
+    }
+
+    private void CloseThread()
+    {
+        _threadOpen = false;
+        _threadRootMessage = null;
+        _threadReplies = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _threadRootId);
+        _threadReplies = [.. _threadReplies, reply];
+        _messages = [.. _messages, reply];
+        _skip++;
+        ComputeReplyCounts();
+    }
+
+    private async Task AddReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+        // Refresh the message list to reflect the new reaction
+        var refreshed = await ChatService.GetMessagesAsync(_selectedChannelId, 0, _skip);
+        _messages = refreshed;
+        ComputeReplyCounts();
+    }
+
+    private void ComputeReplyCounts()
+    {
+        _replyCounts = _messages
+            .Where(m => m.ReplyToId is not null)
+            .GroupBy(m => m.ReplyToId!.Value)
+            .ToDictionary(g => g.Key, g => g.Count());
+
+        // Also include thread replies that may not be in the main list
+        if (_threadOpen && _threadReplies.Count > 0)
+        {
+            _replyCounts[_threadRootId] = Math.Max(
+                _replyCounts.GetValueOrDefault(_threadRootId),
+                _threadReplies.Count);
+        }
+    }
+}
+

